/// <summary>
/// Extension of class ProdJournalCheckPostBOM
/// </summary>
[ExtensionOf(classStr(ProdJournalCheckPostBOM))]
final class AVAProdJournalCheckPostBOMCls_Extension
{
}

Method.Source:
/// <summary>
/// Extension of method createJournalTransfer
/// </summary>
protected void createJournalTransfer()
{
    ProdJournalTable    avaProdJournalTableOld  = ProdJournalTable::find(journalId);
    ProdTable           avaProdTable            = ProdTable::find(avaProdJournalTableOld.ProdId);

    next createJournalTransfer();


    if (transferErrors
        && this.journalErrorListCount() > 0
        && transferJournalId)
    {
        this.avaUpdatePickingErrorJournal(transferJournalId, NoYes::Yes);
        this.avaUpdateProdTablePickingError(avaProdTable.ProdId, NoYes::Yes);
    }
    else if(this.journalErrorListCount() == 0
        && !this.avaHasOtherErrorJournals(avaProdJournalTableOld)
        && avaProdTable.AVAHasPickingErrors == NoYes::Yes)
    {
        this.avaUpdateProdTablePickingError(avaProdTable.ProdId, NoYes::No);
    }
}

/// <summary>
/// Extension of method runPostEnd
/// </summary>
/// <returns>Integer</returns>
protected Integer runPostEnd()
{
    Integer             ret = next runPostEnd();
    ProdJournalTable    avaProdJournalTableOld  = ProdJournalTable::find(journalId);
    ProdTable           avaProdTable            = ProdTable::find(avaProdJournalTableOld.ProdId);

    if (this.numOfPostedLines() == 0)
    {
        this.avaUpdatePickingErrorJournal(journalId, NoYes::Yes);
        this.avaUpdateProdTablePickingError(avaProdTable.ProdId, NoYes::Yes);
    }

    return ret;
}

 /// <summary>
 /// Checks if there is another unposted ErrorJournal for the same ProdId
 /// </summary>
 /// <param name = "_prodJournalTable">ProdJournalTable</param>
 /// <returns>boolean</returns>
 public boolean avaHasOtherErrorJournals(ProdJournalTable _prodJournalTable)
 {
     ProdJournalTable avaProdJournalTable;

     select firstonly RecId from avaProdJournalTable
         where avaProdJournalTable.ProdId    == _prodJournalTable.ProdId
         && avaProdJournalTable.Posted       == NoYes::No
         && avaProdJournalTable.JournalId    != _prodJournalTable.JournalId;

     if(avaProdJournalTable.RecId != 0)
     {
         return true;
     }
     else
     {
         return false;
     }
}

/// <summary>
/// Updates ProdTable record with provided error value
/// </summary>
/// <param name = "_prodId">ProdId</param>
/// <param name = "_hasPickingErrors">NoYes</param>
public void avaUpdateProdTablePickingError(
    ProdId  _prodId,
    NoYes   _hasPickingErrors)
{
    ProdTable prodTableLoc = ProdTable::find(_prodId, true);

    ttsbegin;
    prodTableLoc.AVAHasPickingErrors = _hasPickingErrors;
    prodTableLoc.doUpdate();

    ttscommit;
}

/// <summary>
/// Updates PickingError for ProdJournalTable of provided JournalId
/// </summary>
/// <param name = "_journalId">JournalId</param>
/// <param name = "_hasPickingError">NoYes</param>
public void avaUpdatePickingErrorJournal(
    JournalId _journalId,
    NoYes _hasPickingError)
{
    ProdJournalTable avaProdJournalTable = ProdJournalTable::find(_journalId, true);

    ttsbegin;
    avaProdJournalTable.AVAPickingErrors = _hasPickingError;
    avaProdJournalTable.doUpdate();
    ttscommit;
}
